package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
final class FriendHomeCard {
 private static String initial(String name){String clean=name.replaceFirst("^#[0-9]+\\s+","").trim();return clean.isEmpty()?"?":clean.substring(0,1).toUpperCase(java.util.Locale.ROOT);}
 static LinearLayout create(Context c,String name,String subtitle,String image,String appid,boolean avatar){LinearLayout row=new LinearLayout(c);row.setGravity(android.view.Gravity.CENTER_VERTICAL);row.setPadding(NativeSheet.dp(c,10),NativeSheet.dp(c,8),NativeSheet.dp(c,10),NativeSheet.dp(c,8));row.setBackground(AppStyle.shape(row,0xff201b2c,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,8,0,12);row.setLayoutParams(lp);FrameLayout art=new FrameLayout(c);art.setBackground(AppStyle.shape(art,0xff493172,avatar?32:12));art.setClipToOutline(true);row.addView(art,new LinearLayout.LayoutParams(NativeSheet.dp(c,avatar?42:96),NativeSheet.dp(c,avatar?42:56)));TextView fallback=NativeSheet.text(c,avatar?initial(name):"🎮",24,0xffdfcff9);fallback.setGravity(android.view.Gravity.CENTER);art.addView(fallback,new FrameLayout.LayoutParams(-1,-1));ImageView picture=new ImageView(c);picture.setScaleType(ImageView.ScaleType.CENTER_CROP);art.addView(picture,new FrameLayout.LayoutParams(-1,-1));AccountImageLoader.load(picture,image,appid);LinearLayout copy=new LinearLayout(c);copy.setOrientation(LinearLayout.VERTICAL);copy.setPadding(NativeSheet.dp(c,12),0,0,0);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));TextView title=NativeSheet.text(c,name,14,0xfff4effb);title.setTypeface(null,android.graphics.Typeface.BOLD);copy.addView(title);copy.addView(NativeSheet.text(c,subtitle,12,0xffbfa7ef));return row;}
}
